require_once '../../config/config.php';require_once '../../config/database.php';require_once '../../includes/access.php';
access_require_roles(array('Admin'));$conn->set_charset('utf8mb4');function employee_view_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT * FROM teachers WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$teacher=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$teacher){http_response_code(404);exit('Employee not found.');}$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$login=trim((string)($_POST['login_id']??''));$password=trim((string)($_POST['new_password']??''));if($login===''||$teacher['date_of_birth']==='')$error='Login ID and date of birth are required.';else{$stmt=$conn->prepare("INSERT INTO users (role_id,account_type,linked_id,full_name,username,password,email,mobile,status) VALUES (5,'Teacher',?,?,?,COALESCE(NULLIF(?,''),MD5(DATE_FORMAT((SELECT date_of_birth FROM teachers WHERE id=?),'%d%m%Y'))),?,?,1) ON DUPLICATE KEY UPDATE username=VALUES(username),password=IF(VALUES(password)='',password,VALUES(password)),full_name=VALUES(full_name),email=VALUES(email),mobile=VALUES(mobile),status=1");$stmt->bind_param('isssiss',$id,$teacher['full_name'],$login,$password,$id,$teacher['email'],$teacher['mobile']);if($stmt->execute())$message='Employee login details updated.';else$error=$stmt->error;$stmt->close();}}
?>
