<div class="content-wrapper"><section class="content-header"><div class="container-fluid"><h1>Employee Details</h1></div></section><section class="content"><div class="container-fluid"><?php if($message):?><div class="alert alert-success"><?=employee_view_e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=employee_view_e($error)?></div><?php endif;?><div class="card"><div class="card-body"><h3><?=employee_view_e($teacher['full_name'])?></h3><p>Mobile: <?=employee_view_e($teacher['mobile'])?> | Department: <?=employee_view_e($teacher['department'])?> | Designation: <?=employee_view_e($teacher['designation'])?></p><a class="btn btn-warning" href="edit.php?id=<?=$id?>">Edit Employee</a></div></div><div class="card"><div class="card-header bg-primary text-white">Login ID and Password</div><div class="card-body"><form method="post" class="row"><div class="form-group col-md-4"><label>Login ID</label><input name="login_id" class="form-control" value="<?=employee_view_e($teacher['mobile'])?>" required></div><div class="form-group col-md-4"><label>New Password</label><input name="new_password" class="form-control" placeholder="Blank = DOB DDMMYYYY"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-success">Save Login Details</button></div></form></div></div></div></section></div><?php include '../../includes/footer.php';?>
